select s.id,
s.tenant_code,
s.product_seq,
d.product_code,
d.product_name,
d.unit as product_unit,
s.process_seq,
p.process_code,
p.process_name,
s.pass_num,
s.ng_num,
s.created_by,
s.created_date,
s.last_upd_by,
s.last_upd_date
from micro_process_storage s
left join micro_process_common p on s.tenant_code = p.tenant_code and s.process_seq = p.process_seq
left join micro_product d on s.tenant_code = d.tenant_code and s.product_seq = d.product_seq

    and s.tenant_code = #{tenantCode}
    and s.product_seq = #{productSeq}
    and s.process_seq = #{processSeq}
    and s.pass_num = #{passNum}
    and s.ng_num = #{ngNum}
    and s.created_by = #{createdBy}
    and s.created_date = #{createdDate}
    and s.last_upd_by = #{lastUpdBy}
    and s.last_upd_date = #{lastUpdDate}

        and (
        p.process_code like concat('%', #{processNameOrCode}, '%')
        or
        p.process_name like concat('%', #{processNameOrCode}, '%')
        )


order by s.last_upd_date desc

SELECT max( s.id ) AS id, max( s.tenant_code ) AS tenant_code, max( s.product_seq ) AS product_seq, max( d.id) AS product_id, max( d.product_code ) AS product_code, max( d.product_name ) AS product_name, max( d.unit ) AS product_unit, max( s.process_seq ) AS process_seq, max( p.process_code ) AS process_code, max( p.process_name ) AS process_name, IFNULL( MIN( mws.is_last_process ), 1 ) AS is_last_process, IFNULL( MIN( mws.is_first_process ), 1 ) AS is_first_process, max( s.pass_num ) AS pass_num, max( s.ng_num ) AS ng_num, max( s.created_by ) AS created_by, max( s.created_date ) AS created_date, max( s.last_upd_by ) AS last_upd_by, max( s.last_upd_date ) AS last_upd_date FROM micro_process_storage s LEFT JOIN micro_process_common p ON s.tenant_code = p.tenant_code AND s.process_seq = p.process_seq LEFT JOIN micro_work_submit mws ON s.tenant_code = mws.tenant_code AND mws.operate_process_seq = s.process_seq AND mws.product_seq = s.product_seq LEFT JOIN micro_product d ON s.tenant_code = d.tenant_code AND s.product_seq = d.product_seq WHERE 1=1
and ( s.process_seq = #{seqKey} or s.product_seq = #{seqKey} )
and s.product_seq = #{productSeq}
and s.process_seq = #{processSeq}
GROUP BY s.product_seq, s.process_seq ORDER BY s.last_upd_date DESC

